using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class ClearGlass12Fix{
 const string Done="D:/-11-scene3-audit/glass12-frosted.txt";static double next;static ClearGlass12Fix(){EditorApplication.update+=Tick;EditorApplication.delayCall+=Run;}static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+5;Run();}
 [MenuItem("Tools/Scene3/Apply Clear Glass1 Glass2")]static void Run(){if(File.Exists(Done)||EditorApplication.isUpdating||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.path!="Assets/Scenes/scene3.unity")return;
 try{var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var shader=Shader.Find("BlenderScene3/ClearArchitecturalGlass");if(!shader||ShaderUtil.ShaderHasError(shader))throw new Exception("Glass shader did not compile");var report=new List<string>();var targets=new List<Renderer>();
 foreach(var name in new[]{"glass1","glass2"}){var found=ts.Where(t=>string.Equals(t.name.Trim(),name,StringComparison.OrdinalIgnoreCase)).ToArray();if(found.Length==0 && name=="glass1")found=ts.Where(t=>string.Equals(t.name.Trim(),"glass",StringComparison.OrdinalIgnoreCase)).ToArray();if(found.Length==0)throw new Exception("Object missing: "+name+"; glass candidates="+string.Join(",",ts.Where(t=>t.name.ToLower().Contains("glass")).Select(t=>t.name)));var rs=found.SelectMany(t=>t.GetComponentsInChildren<Renderer>(true)).Distinct().ToArray();if(rs.Length==0)throw new Exception("No renderer: "+name);targets.AddRange(rs);}
 EditorSceneManager.SaveScene(s);File.Copy(s.path,"D:/-11-scene3-audit/scene3.before-frosted-glass.unity",true);
 foreach(var r in targets.Distinct()){var p="Assets/BlenderScene3/Materials/ClearGlass_"+(r.name.ToLower().Contains("glass2")?"2":"1")+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(p);if(!mat){mat=new Material(shader);AssetDatabase.CreateAsset(mat,p);}mat.shader=shader;mat.SetColor("_Color",new Color(.92f,.97f,1,.05f));mat.SetFloat("_Smoothness",.70f);mat.SetFloat("_Frost",2.5f);mat.renderQueue=3000;EditorUtility.SetDirty(mat);Undo.RecordObject(r,"Make glass1 glass2 transparent glass");var before=r.sharedMaterials.Length;r.sharedMaterials=Enumerable.Repeat(mat,Math.Max(1,before)).ToArray();r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;r.reflectionProbeUsage=UnityEngine.Rendering.ReflectionProbeUsage.BlendProbes;PrefabUtility.RecordPrefabInstancePropertyModifications(r);report.Add(r.name+"|active="+r.gameObject.activeInHierarchy+"|slots="+r.sharedMaterials.Length+"|opacity="+mat.GetColor("_Color").a+"|smoothness="+mat.GetFloat("_Smoothness")+"|shader="+r.sharedMaterial.shader.name);}
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllLines(Done,report);Selection.objects=targets.Select(r=>(UnityEngine.Object)r.gameObject).ToArray();SceneView.RepaintAll();
 }catch(Exception ex){File.WriteAllText("D:/-11-scene3-audit/glass12-error.txt",ex.ToString());}}
}


